Here is the root cause:
The bug occurred because `mseal_apply()` used a mutable `curr_start` variable that was updated to `curr_end` after each VMA iteration. However, when a VMA was modified (e.g., merged) via `vma_modify_flags()`, the stored `curr_end` could become stale—still pointing to the old VMA's end—so setting `curr_start = curr_end` would advance to an incorrect start address for the next iteration, potentially causing missed or misaligned range processing.

Here is the patch:

 static int mseal_apply(struct mm_struct *mm,
 		unsigned long start, unsigned long end)
 {
 	struct vm_area_struct *vma, *prev;
-	unsigned long curr_start = start;
 	VMA_ITERATOR(vmi, mm, start);

 	/* We know there are no gaps so this will be non-NULL. */
 	vma = vma_iter_load(&vmi);
 	prev = vma_prev(&vmi);
 	if (start > vma->vm_start)
 		prev = vma;

 	for_each_vma_range(vmi, vma, end) {
+		const unsigned long curr_start = MAX(vma->vm_start, start);
 		const unsigned long curr_end = MIN(vma->vm_end, end);

 		if (!(vma->vm_flags & VM_SEALED)) {
 			vm_flags_t vm_flags = vma->vm_flags | VM_SEALED;

 			vma = vma_modify_flags(&vmi, prev, vma, curr_start,
 					       curr_end, &vm_flags);
 			if (IS_ERR(vma))
 				return PTR_ERR(vma);
 			vm_flags_set(vma, VM_SEALED);
 		}

 		prev = vma;
-		curr_start = curr_end;
 	}

 	return 0;
 }



